/* sds-textarea — an answer of more than one line.

   Its own element and not a taller field, for the reason a select is its own
   element. What it shares with a text field is the sunken box, and what it does
   not share is everything a caller writes. A textarea has lines and a direction
   to drag it in, its value can hold a newline, and `pattern` and `inputmode`
   mean nothing to it.

   A real `<textarea>`, assembled as a string. Lit refuses a binding between the
   tags of a raw text element. Its content is the only place a value lives
   where a file with no script still shows it. So the listener sits on the box
   around it, and the event bubbles up to it. */

import { html, nothing, type TemplateResult } from 'lit';
import { unsafeHTML } from 'lit/directives/unsafe-html.js';
import { define } from '../lib/element.ts';
import { fieldBox, type FieldSize } from '../lib/field-box.ts';
import { fieldRow } from '../lib/field-row.ts';
import { SdsFormElement } from '../lib/form-element.ts';

/** The characters an attribute value and text content cannot hold raw — the
    value a user typed goes into both. */
const esc = (s: string): string =>
  s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** Which way a reader can drag the corner. `vertical` is the default because a
    box that widens breaks the column it stands in. */
export type TextareaResize = 'vertical' | 'none' | 'both';

export interface TextareaProps {
  /** Lines. The room the box *deserves*, not a limit on the answer. */
  rows?: number;
  /** What is in it — its value when `filled`, its placeholder when not. */
  value?: string;
  /** The visible label, which turns this into a control in a *form*: label
      above, hint under, error under both. */
  caption?: string;
  /** Its name, for anything that cannot see what it sits beside. */
  label?: string;
  /** The name the value travels under when the form submits. */
  name?: string;
  /** The control's id, so the label points at it and an error summary can. */
  fieldId?: string;
  /** What the answer has to be, under the control. Never inside it. */
  hint?: string;
  /** What is wrong with what is in it. Sets the invalid state with it, and the
      browser refuses to submit past it. */
  error?: string;
  /** Said in words beside the label. */
  required?: boolean;
  /** Present, and not on offer. */
  disabled?: boolean;
  /** Shown and sent, and not editable. */
  readonly?: boolean;
  /** How much a reader can type — the browser's own limit. */
  maxlength?: number;
  /** What the browser can fill in. */
  autocomplete?: string;
  /** Which way the corner drags. */
  resize?: TextareaResize;
  /** The three heights a button has, which here set the type and the padding
      rather than a height: the lines do that. */
  size?: FieldSize;
  /** The width it asks for, in pixels. The attribute is `min-width`. */
  minWidth?: number;
  /** The value is the reader's, not a prompt. A keystroke sets it too. */
  filled?: boolean;
  /** Force the states a still picture cannot hold. */
  focused?: boolean;
  invalid?: boolean;
}

export class SdsTextarea extends SdsFormElement {
  static override properties = {
    rows: { type: Number },
    value: { type: String },
    caption: { type: String },
    label: { type: String },
    name: { type: String },
    fieldId: { type: String, attribute: 'field-id' },
    hint: { type: String },
    error: { type: String },
    required: { type: Boolean, reflect: true },
    disabled: { type: Boolean, reflect: true },
    readonly: { type: Boolean, reflect: true },
    maxlength: { type: Number },
    autocomplete: { type: String },
    resize: { type: String, reflect: true },
    size: { type: String, reflect: true },
    minWidth: { type: Number, attribute: 'min-width' },
    filled: { type: Boolean, reflect: true },
    focused: { type: Boolean, reflect: true },
    invalid: { type: Boolean, reflect: true },
  };

  declare rows: number;
  declare value: string;
  declare caption: string;
  declare label?: string;
  declare name: string;
  declare fieldId: string;
  declare hint: string;
  declare error: string;
  declare required: boolean;
  declare disabled: boolean;
  declare readonly: boolean;
  declare maxlength: number;
  declare autocomplete: string;
  declare resize: TextareaResize;
  declare size: FieldSize;
  declare minWidth: number;
  declare filled: boolean;
  declare focused: boolean;
  declare invalid: boolean;

  constructor() {
    super();
    this.rows = 4;
    this.value = '';
    this.caption = '';
    this.name = '';
    this.fieldId = '';
    this.hint = '';
    this.error = '';
    this.required = false;
    this.disabled = false;
    this.readonly = false;
    this.maxlength = 0;
    this.autocomplete = '';
    this.resize = 'vertical';
    this.size = 'md';
    this.minWidth = 420;
    this.filled = false;
    this.focused = false;
    this.invalid = false;
  }

  /* What the markup came with: what the element holds at first, and what a
     reset puts back. Read once, before the first keystroke. */
  #initial?: string;

  protected override willUpdate(): void {
    this.#initial ??= this.filled ? this.value : '';
  }

  protected override updated(changed: Map<PropertyKey, unknown>): void {
    /* The control is a string drawn once, so typing never replaces it. Its
       content is the *default* a reset puts back. The attributes and the real
       value go onto the live control here. The guard keeps the caret still:
       the same string assigned again moves it to the end. */
    const area = this.querySelector('textarea');
    if (area) {
      for (const [key, value] of Object.entries(this.attrs())) {
        if (value === null) area.removeAttribute(key);
        else if (area.getAttribute(key) !== value) area.setAttribute(key, value);
      }
      const written = this.filled ? this.value : '';
      if (area.value !== written) area.value = written;
    }
    if (changed.has('error') || !this.#validated) this.setValidity(this.error, 'textarea');
    this.#validated = true;
  }
  #validated = false;

  /* Every attribute the control carries, `null` for one it has not. */
  private attrs(): Record<string, string | null> {
    const disabled = this.disabled || this.inheritedDisabled;
    const or = (value: string): string | null => value || null;
    return {
      rows: String(this.rows),
      id: or(this.fieldId),
      name: or(this.name),
      placeholder: this.filled ? null : or(this.value),
      'aria-label': or(this.label ?? ''),
      autocomplete: or(this.autocomplete),
      maxlength: this.maxlength ? String(this.maxlength) : null,
      'aria-invalid': this.invalid || this.error ? 'true' : null,
      required: this.required ? '' : null,
      disabled: disabled ? '' : null,
      readonly: this.readonly ? '' : null,
    };
  }

  /* The control as the first render wrote it. A prerendered page submits it
     before a script runs, so it carries every attribute then. */
  #drawn?: string;

  protected override restore(): void {
    this.value = this.#initial || this.value;
    this.filled = !!this.#initial;
  }

  private onInput(event: Event): void {
    const area = event.target as HTMLTextAreaElement;
    this.value = area.value;
    this.filled = area.value !== '';
    /* A keystroke answers whatever was wrong. The caller decides what is
       wrong next; the old sentence left in place blocks the form on a value
       nobody has judged yet. */
    this.error = '';
    this.dispatchEvent(new CustomEvent<string>('sds-input', { detail: area.value, bubbles: true, composed: true }));
  }

  protected override render(): TemplateResult {
    const cls = `${fieldBox(this)} sds-field--multi`;
    const box = `width:${this.minWidth}px; max-width:100%`;
    const written = Object.entries(this.attrs())
      .map(([key, value]) => (value === null ? '' : value === '' ? ` ${key}` : ` ${key}="${esc(value)}"`))
      .join('');
    const area = (this.#drawn ??= `<textarea class="sds-input"${written}>${esc(this.#initial ?? '')}</textarea>`);

    const control = html`<span class="${cls}" style="${box}" @input="${(e: Event) => this.onInput(e)}">${unsafeHTML(area)}</span>`;
    return fieldRow(this, control);
  }
}

define('sds-textarea', SdsTextarea);
