/* sds-result — one hit in a list of them.

   The find, **where it is**, the sentence around it, and what kind of thing it
   is. The second is what a list of titles and snippets leaves out, and the
   reader opens a page to learn it. The hit is an anchor: the whole of it is
   the link, named by its heading.

   The mark on the match happens here, not in the caller. The highlight must
   be the query, and a page that marks by hand marks what it thinks the query
   was. Not `sds-card`: that invites, this answers. */

import { html, nothing, type TemplateResult } from 'lit';
import './badge.ts';
import { art, exported } from '../lib/art.ts';
import { define, SdsElement } from '../lib/element.ts';

export interface SearchResultProps {
  /** The page's name. The whole row is the link to it, not the title
      alone. */
  heading: string;
  /** Where the hit goes, already resolved — a path out of the index is
      relative to the root, and a reader is rarely standing in it. */
  href?: string;
  /** Where it is, as the site's own trail — `Documentation · Tools`. Mono,
      because a path is a machine-named thing. */
  path?: string;
  /** The sentence around the find, cut from the text and not written for the
      list. */
  snippet?: string;
  /** The query. Every occurrence of each of its words in the snippet and the
      heading gets a mark. */
  match?: string;
  /** What kind of thing it is — reference, guide, changelog. */
  kind?: string;
  /** The release it holds for, where it holds for one. */
  meta?: string;
  /** The picture the thing found carries, where it has one. Named `src`
      because everything in this system that takes a file names it `src`. */
  src?: string;
  /** What the thumbnail shows. Empty where it adds nothing the heading has
      not said. */
  alt?: string;
}

/** The first place at or after `from` where a word of the query starts. Where
    two words start at the same place, the longer one wins. */
function nearest(hay: string, words: string[], from: number): { at: number; length: number } | undefined {
  let best: { at: number; length: number } | undefined;
  for (const word of words) {
    const at = hay.indexOf(word, from);
    if (at === -1) continue;
    if (!best || at < best.at || (at === best.at && word.length > best.length)) best = { at, length: word.length };
  }
  return best;
}

export class SdsSearchResult extends SdsElement {
  static override properties = {
    heading: { type: String },
    href: { type: String },
    path: { type: String },
    snippet: { type: String },
    match: { type: String },
    kind: { type: String },
    meta: { type: String },
    src: { type: String },
    alt: { type: String },
  };

  declare heading: string;
  declare href: string;
  declare path: string;
  declare snippet: string;
  declare match: string;
  declare kind: string;
  declare meta: string;
  declare src: string;
  declare alt: string;

  constructor() {
    super();
    this.heading = '';
    this.href = '#';
    this.path = '';
    this.snippet = '';
    this.match = '';
    this.kind = '';
    this.meta = '';
    this.src = '';
    this.alt = '';
  }

  /** The text with every occurrence of each word of the query in a `<mark>`.

      Split rather than replaced, so nothing ever lands as markup. What comes
      back is text nodes and elements, and a query with `<` in it is a query
      and not a tag. */
  private marked(text: string): unknown {
    const words = this.match.trim().toLowerCase().split(/\s+/).filter(Boolean);
    if (!words.length || !text) return text;

    const out: unknown[] = [];
    const hay = text.toLowerCase();
    let at = 0;
    for (let next = nearest(hay, words, at); next; next = nearest(hay, words, at)) {
      if (next.at > at) out.push(text.slice(at, next.at));
      out.push(html`<mark class="sds-mark">${text.slice(next.at, next.at + next.length)}</mark>`);
      at = next.at + next.length;
    }
    out.push(text.slice(at));
    return out;
  }

  /* Beside the text rather than over it. A reader reads a hit as a line, and
     a picture on top of one makes a list of them a grid of cards. Empty `alt`
     where the caller wrote none — the title names the target already, and a
     second name for it is the same page announced twice. */
  private thumb(): unknown {
    if (!this.src) return nothing;
    const kind = exported(this.src) ? ' sds-result__thumb--exported' : '';
    return html`<div class="sds-result__thumb${kind}">${art(this.src, this.alt)}</div>`;
  }

  /* What kind of thing it is, where it is and what it holds for, on one line.
     The line goes rather than stays empty. A source that reports none of the
     three has no structure to report. A blank first row is a hole above
     every title in the list. */
  private above(): unknown {
    if (!this.kind && !this.path && !this.meta) return nothing;
    return html`<span class="sds-row">
      ${this.kind ? html`<sds-badge label="${this.kind}"></sds-badge>` : nothing}
      ${this.path ? html`<span class="sds-result__path">${this.path}</span>` : nothing}
      ${this.meta ? html`<span class="sds-result__meta">${this.meta}</span>` : nothing}
    </span>`;
  }

  /** The whole hit is the link, so the hit *is* an anchor. One element rather
      than a title's anchor stretched over the row by a pseudo-element. That
      is what a card does, and it costs a reader the text selection. Named by
      its heading: without that the link's name is everything in the row read
      out at once. Nowhere to go, no anchor. */
  protected override render(): TemplateResult {
    const body = html`${this.thumb()}
  <span class="sds-result__body">
    ${this.above()}
    <h3 class="sds-result__title">${this.marked(this.heading)}</h3>
    ${this.snippet ? html`<p class="sds-result__text">${this.marked(this.snippet)}</p>` : nothing}
  </span>`;

    return this.href
      ? html`<a class="sds-result" href="${this.href}" aria-label="${this.heading}">${body}</a>`
      : html`<article class="sds-result">${body}</article>`;
  }
}

define('sds-search-result', SdsSearchResult);
